/**
 * The models the playground documents are the compiler's output, generated by
 * `pnpm build:autodoc-example`. They are declared here so the example type-checks
 * on a tree where they have not been generated; `asAst` is the one boundary that
 * reads the JSON.
 */
declare module '*.publicodes.js' {
	import type { CompiledModule } from '@publicodes/autodoc-core'

	const rules: CompiledModule['default']
	export const outputs: CompiledModule['outputs']
	export const parameters: CompiledModule['parameters']
	export default rules
}

declare module '*.publicodes.json' {
	const ast: unknown
	export default ast
}
